<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Result Verification</title><style>body{font-family:Arial,sans-serif;background:#f1f5f9;margin:0;padding:32px;color:#172033}.card{max-width:680px;margin:30px auto;background:white;border-radius:16px;padding:28px;box-shadow:0 8px 28px #0f172a12}.ok{color:#047857;font-weight:700}.muted{color:#64748b}table{width:100%;border-collapse:collapse;margin-top:20px}td{padding:10px;border:1px solid #e2e8f0}</style></head><body><main class="card"><h1>{{ $data['school']['name'] }}</h1><p class="muted">{{ $data['school']['address'] }}</p><h2 class="ok">✓ Authentic published result</h2><p>This result is verified against the school's result database.</p><table><tr><td>Student</td><td>{{ $data['student']['name'] }}</td></tr><tr><td>Roll</td><td>{{ $data['student']['roll'] }}</td></tr><tr><td>Class</td><td>{{ $data['student']['class_name'] }}</td></tr><tr><td>Exam</td><td>{{ $data['student']['exam_name'] }} {{ $data['student']['exam_year'] }}</td></tr><tr><td>GPA</td><td>{{ number_format((float)$data['summary']['gpa'],2) }}</td></tr><tr><td>Result</td><td>{{ $data['summary']['result'] }}</td></tr></table><p class="muted">School Result Management System</p></main></body></html>